const CE = [['Yargının açıkça belirtilmesi (teknoloji)', 'değerlendirme sorusuna açık bir yargı verir'], ['Gerekçenin görüşe dayandırılması (teknoloji)', 'yargısını görüşün kendi iddiasına ya da bir örneğe dayanarak gerekçelendirir'], ['Karşı noktanın hesaba katılması (teknoloji)', 'yargısına yöneltilebilecek bir karşı noktaya değinir']] as [[string, string], [string, string], [string, string]];
const CC = [['Özgün ürünün yazılması (teknoloji)', 'istenen ürünü (durum, soru, argüman, diyalog, paragraf) özgün biçimde yazar'], ['Ürünün göreve uygunluğu (teknoloji)', 'ürünün görevde istenen görüş, kavram ya da soruyla ilgisini gösterir'], ['Ürünün tutarlılığı (teknoloji)', 'ürünü kendi içinde ve metindeki görüşlerle çelişmeden kurar']] as [[string, string], [string, string], [string, string]];
